<script setup lang="ts">
import {computed,ref} from 'vue'
import TutorCard from '../../components/TutorCard.vue'
import {tutors} from '../../mocks/tutors'
const query=ref(''),subject=ref('全部'),teachingMode=ref('全部')
const teachingModes=['全部','线上','线下']
const subjects=['全部','数学','英语','语文','物理','化学']
const filtered=computed(()=>tutors.filter(t=>(subject.value==='全部'||t.subjects.includes(subject.value))&&(teachingMode.value==='全部'||t.teachingMode==='均可'||t.teachingMode===teachingMode.value)&&[t.name,t.university,t.area,...t.subjects,...t.tags].join(' ').toLowerCase().includes(query.value.trim().toLowerCase())))
const go=(url:string)=>uni.navigateTo({url})
</script>
<template><view class="page"><view class="hero"><text class="eyebrow">校园家教 · 连接好老师</text><text class="headline">找到适合自己的学习伙伴</text><text class="intro">按科目筛选老师，查看教学信息，轻松发起演示预约。</text><view class="links"><text @click="go('/pages/orders/index')">我的预约 →</text><text @click="go('/pages/profile/index')">个人中心 →</text></view></view><input class="search" v-model="query" placeholder="搜索科目、地区或老师姓名"/><view class="heading">按科目查找</view><scroll-view scroll-x><view class="filters"><text v-for="s in subjects" :key="s" class="chip" :class="{active:subject===s}" @click="subject=s">{{s}}</text></view></scroll-view><view class="heading">授课方式</view><view class="filters"><text v-for="mode in teachingModes" :key="mode" class="chip" :class="{active:teachingMode===mode}" @click="teachingMode=mode">{{mode}}</text></view><view class="heading">推荐家教 <text class="count">{{filtered.length}} 位演示老师</text></view><TutorCard v-for="t in filtered" :key="t.id" :tutor="t" @open="id=>go('/pages/tutors/detail?id='+id)"/><view v-if="!filtered.length" class="empty">没有匹配的老师，换个关键词试试。</view><view class="notice">所有老师、价格及教学信息均为虚构演示数据，未经过身份认证。</view></view></template>
<style scoped>.page{padding:25rpx}.hero{background:linear-gradient(135deg,#1852c8,#3c8be9);border-radius:26rpx;padding:40rpx 30rpx;color:#fff;display:flex;flex-direction:column}.eyebrow{font-size:23rpx;opacity:.85}.headline{font-size:40rpx;font-weight:800;margin-top:20rpx}.intro{font-size:24rpx;line-height:1.6;opacity:.9;margin-top:15rpx}.links{display:flex;gap:22rpx;margin-top:26rpx;font-size:25rpx}.links text{background:#ffffff33;padding:13rpx 18rpx;border-radius:50rpx}.search{background:#fff;border-radius:16rpx;padding:20rpx 24rpx;height:90rpx;margin-top:25rpx;font-size:26rpx}.heading{font-size:31rpx;font-weight:700;margin:35rpx 0 20rpx}.count{font-size:22rpx;color:#8590a4;font-weight:400;float:right}.filters{display:flex;gap:12rpx;padding-bottom:8rpx}.chip{flex-shrink:0;background:#fff;color:#54637b;border-radius:60rpx;padding:16rpx 27rpx;font-size:24rpx}.active{background:#2868e4;color:#fff}.notice,.empty{text-align:center;color:#929aab;font-size:22rpx;line-height:1.7;margin:30rpx 0}</style>
